files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  font-family: Inter, sans-serif;
  background-image: url(../images/bg.jpg);
  background-position: center top;
  background-size: cover;
}

.popup {
  display: flex;
  position: fixed;
  inset: 0;
  background-color: rgb(0 0 0/0.8);
}

.popup__content {
  margin: auto;
  position: relative;
  width: 600px;
  border-radius: 10px;
  padding: 40px;
  font-size: 16px;
  line-height: 1.35;
  background-color: #fff;
}

.close-popup {
  position: absolute;
  top: 0;
  right: 0;
  width: 18px;
  height: 18px;
  border: none;
  padding: 0;
  background-color: transparent;
  transform: translate(100%, -100%);
}

.close-popup img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}
